sections.text:
נתונה המחלקה AllCars שיש לה שתי תכונות:
cars: מערך חד־ממדי מטיפוס Car
num: מספר המכוניות הנוכחי שיש בחברה, מטיפוס שלם
לפניך הפעולה הבונה של המחלקה:
public AllCars(int max)
{
    this.cars = new Car[max];
    this.num = 0;
}
(1) כתוב במחלקה AllCars פעולה פנימית בוליאנית בשם addCar, המקבלת עצם מטיפוס Car. הפעולה מוסיפה אותו למערך המכוניות במקום הראשון הפנוי ומחזירה true.
אם המערך מלא, תחזיר הפעולה false.
הנח שאין מקומות פנויים מהתחלת המערך ועד למספר num (לא כולל num).

classes.code:
public class Car {
    private String licenseNum;
    private boolean hadAccident;
    private int price;

    public Car(String licenseNum, boolean hadAccident, int price) {
        this.licenseNum = licenseNum;
        this.hadAccident = hadAccident;
        this.price = price;
    }

    public String getLicenseNum() { return licenseNum; }
    public void setLicenseNum(String licenseNum) { this.licenseNum = licenseNum; }
    public boolean getHadAccident() { return hadAccident; }
    public void setHadAccident(boolean hadAccident) { this.hadAccident = hadAccident; }
    public int getPrice() { return price; }
    public void setPrice(int price) { this.price = price; }
}

public class AllCars {
    private Car[] cars;
    private int num;

    public AllCars(int max) {
        this.cars = new Car[max];
        this.num = 0;
    }

    public Car[] getCars() { return cars; }
    public int getNum() { return num; }
}

tasks.solution:
public boolean range(int min, int max) {
    return price >= min && price <= max;
}

public boolean addCar(Car c) {
    if (num < cars.length) {
        cars[num] = c;
        num++;
        return true;
    }
    return false;
}

public void print(int min, int max) {
    for (int i = 0; i < num; i++) {
        if (!cars[i].getHadAccident() && cars[i].range(min, max)) {
            System.out.println(cars[i].getLicenseNum());
        }
    }
}

givenCode.code:
public static String check(Object got, Object expected) {
    String g = String.valueOf(got);
    String e = String.valueOf(expected);
    if (g.equals(e)) {
        return "נכון";
    }
    return "לא נכון — התקבל " + g + ", צריך להתקבל " + e;
}

exercise.mainCode:
Car c1 = new Car("11-222-33", false, 80000);
Car c2 = new Car("44-555-66", true, 90000);
Car c3 = new Car("77-888-99", false, 120000);
Car c4 = new Car("12-345-67", false, 95000);
System.out.println("סעיף א, בדיקה 1: " + check(c1.range(70000, 100000), true));
System.out.println("סעיף א, בדיקה 2 (שווה ל-min): " + check(c1.range(80000, 100000), true));
System.out.println("סעיף א, בדיקה 3 (שווה ל-max): " + check(c1.range(50000, 80000), true));
System.out.println("סעיף א, בדיקה 4: " + check(c3.range(70000, 100000), false));
AllCars small = new AllCars(3);
System.out.println("סעיף ב, בדיקה 1: " + check(small.addCar(c1), true));
System.out.println("סעיף ב, בדיקה 2: " + check(small.addCar(c2), true));
System.out.println("סעיף ב, בדיקה 3: " + check(small.addCar(c3), true));
System.out.println("סעיף ב, בדיקה 4 (המערך מלא): " + check(small.addCar(c4), false));
System.out.println("סעיף ב, בדיקה 5: " + check(small.getNum(), 3));
AllCars all = new AllCars(10);
all.addCar(c1);
all.addCar(c2);
all.addCar(c3);
all.addCar(c4);
System.out.println("סעיף ג, בדיקה 1: בין 80000 ל-100000 צריך להדפיס את 11-222-33 ואחריו את 12-345-67:");
all.print(80000, 100000);
System.out.println("סעיף ג, בדיקה 2: בין 100000 ל-200000 צריך להדפיס את 77-888-99:");
all.print(100000, 200000);
System.out.println("סעיף ג, בדיקה 3: בין 1 ל-1000 לא צריך להדפיס כלום:");
all.print(1, 1000);
System.out.println("סעיף ג: סוף הבדיקות");

